'use strict';
/* public/js/45-state.js -- player/session state, digging, world interactions (use/F). Generated by scripts/split-client.mjs; see ARCHITECTURE.md. */
/* ---------- game state ---------- */
const S={started:false,seeds:20,hp:100,hurtT:99,water:100,sack:[],onions:1,onionT:0,up:{},ko:0,hasKB:false,reported:false,revealed:false,won:false,detOn:true,name:'Caveman',color:0,holesDone:0,carry:null,noise:0,batt:100,light:false,revT:0,climbT:0,respawnAt:0,tent:null,tentBack:null,inBed:null};
let GOD=false;   // god mode (console: god): no damage, no knockouts, water never runs out -- for testing and recording
const P={x:0,z:39,y:0,vy:0,kx:0,kz:0,fa:Math.PI,yaw:0,pitch:0.32,digT:0,digPh:0,anim:0,grounded:true,moving:false};
P.y=groundAt(P.x,P.z);
let me=null,meL=null;
const KEYS={};let digHeld=false;

/* first / third person (V) and the first-person shovel */
let FP=false;
const pc=v=>clamp(v,FP?-1.35:-0.15,FP?1.35:1.25);
function toggleView(){FP=!FP;if(me)me.g.visible=!FP;P.pitch=FP?0.05:0.32;toast(FP?'First person. Press V to switch back.':'Third person','',1500)}
const vm=new T.Group();
{const hd=new T.Mesh(new T.CylinderGeometry(0.02,0.02,0.9,5),M(0x8a6440));hd.rotation.x=Math.PI/2;hd.position.z=-0.25;const bl=new T.Mesh(new T.BoxGeometry(0.22,0.02,0.26),M(0x7d8288));bl.position.z=-0.78;const sh=new T.Group();sh.rotation.x=-0.35;sh.add(hd,bl);vm.add(sh)}
vm.position.set(0.34,-0.4,-0.55);vm.visible=false;camera.add(vm);
function updateViewmodel(){vm.visible=FP&&S.started&&!S.ko&&!twSt&&!tbSt;if(!vm.visible)return;const d=P.anim===2?Math.sin(P.digPh*Math.PI):0,b=P.moving?Math.sin(performance.now()/110)*0.012:0;vm.rotation.x=-d*0.9;vm.position.set(0.34+b,-0.4-d*0.05+Math.abs(b),-0.55-d*0.2)}

function waterMax(){return (S.up.canteen?160:100)+(myLevel()>=4?20:0)}
function digDepthMax(){return S.up.long?EIGHT_FT:FIVE_FT}
/* toast variants (docs/ui-redesign-spec.md section 4): existing call sites keep passing the old
   class names ('good'/'gold'/'bad'/'') -- toast() maps them to the spec's success/reward/warning/
   neutral vocabulary (and picks an icon) so nothing elsewhere needs to change. An identical
   message+variant within 2s refreshes the existing toast's timer instead of stacking a duplicate. */
const TOAST_VARIANT={good:'success',gold:'reward',bad:'warning','':'neutral'};
const TOAST_ICON={success:'check',reward:'seed',warning:'lizard',neutral:'ping'};
const recentToasts=new Map();
function toast(msg,cls,ms){
  const variant=TOAST_VARIANT[cls||'']||'neutral',key=variant+'|'+msg,now=performance.now();
  const dup=recentToasts.get(key);
  if(dup&&now-dup.t<2000){
    dup.t=now;clearTimeout(dup.timer);dup.timer=setTimeout(()=>{dup.el.remove();recentToasts.delete(key)},ms||3600);
    dup.el.classList.remove('toast--refresh');void dup.el.offsetWidth;dup.el.classList.add('toast--refresh');
    return;
  }
  const el=document.createElement('div');el.className=`toast toast--${variant}`;el.setAttribute('role','status');
  const icon=document.createElement('span');icon.className='toast__icon';icon.setAttribute('aria-hidden','true');
  icon.innerHTML=`<svg class="ui-icon"><use href="#icon-${TOAST_ICON[variant]}"></use></svg>`;
  const txt=document.createElement('span');txt.className='toast__text';txt.textContent=msg;
  el.append(icon,txt);
  const box=$('#toasts');box.appendChild(el);while(box.children.length>4){const old=box.firstChild;for(const[k,v]of recentToasts)if(v.el===old){clearTimeout(v.timer);recentToasts.delete(k);break}old.remove()}
  const timer=setTimeout(()=>{el.remove();recentToasts.delete(key)},ms||3600);
  recentToasts.set(key,{el,t:now,timer});
}

/* ---------- digging ---------- */
let lastWarn=0;
function scoop(){
  if(!inSinkhole()&&remoteNear(R=>R.f&32,SINK_RESCUE_R))return;   // E at a trapped friend's rim links hands (87-sinkhole.js), it doesn't dig
  if(vShoo())return;   // a well-timed swing while a vulture is diving close in front of you chases it off (83-vultures.js)
  if(javSwing())return;   // a live javelina in shovel reach gets whacked instead of the ground getting dug
  if(lionSwing())return;   // the mountain lion is in melee range: this shovel swing hits it instead of digging (see 85-lion.js)
  if(bonkSwing())return;   // a friend (or crew member) right in front of you: the swing bonks them instead (71-bonk.js)
  if(inSinkhole()){const now=performance.now();if(now-lastWarn>3000){lastWarn=now;toast('The walls are too steep and loose to dig footholds. Only a friend can pull you out.','bad')}return}
  const fx=Math.sin(P.fa),fz=Math.cos(P.fa);
  const tx=P.x+fx*1.1,tz=P.z+fz*1.1;
  let h=holeNear(P.x,P.z,HOLE_R*0.8)||holeNear(tx,tz,1.4);
  const now=performance.now();
  const cx=h?h.x:tx,cz=h?h.z:tz;
  if(inCamp(cx,cz)){if(now-lastWarn>2500){say(sirL,'Not in camp! Go dig on the lake.');toast('No digging inside camp. Head out onto the lake bed.','bad');lastWarn=now}return}
  if(Math.max(Math.abs(cx),Math.abs(cz))>EDGE-2){if(now-lastWarn>2500){toast('That\'s the edge of the lake. Dig closer in.','bad');lastWarn=now}return}
  const maxD=digDepthMax();
  if(!h){h=addHole({x:r1(tx),z:r1(tz),d:0,mine:true,own:true})}
  if(h.d>=maxD-0.001){
    if(now-lastWarn>3000){lastWarn=now;if(maxD<EIGHT_FT)toast('That\'s 5 feet, as deep as your shovel reaches. A long-handled shovel from the Wreck Room goes to 8 feet.');else toast('8 feet. Your shovel won\'t go any deeper.')}
    sfx.thud();return;
  }
  const step=(S.up.spade?0.15:0.088)*(S.zeroT>0?2:1)*(myLevel()>=2?1.1:1);addXP(0.3);
  h.d=Math.min(maxD,h.d+step);
  touchHole(h);h.mine=true;wsSend({t:'dig',x:h.x,z:h.z,d:+h.d.toFixed(2)});
  const y=groundAt(h.x,h.z)+0.4;puff(h.x+(Math.random()-0.5)*0.6,y,h.z+(Math.random()-0.5)*0.6,h.mx,h.mz,6);sfx.scoop();throwClods(h,2);   // clods arc onto the spoil pile (46-holes.js)
  if(h.own&&!h.paid&&h.d>=FIVE_FT){h.paid=true;S.seeds+=3;S.holesDone++;addXP(10);toast(`Hole #${S.holesDone} finished. Five feet deep, five feet across. +3 seeds`,'good');sfx.coin()}
  for(const it of items){
    if(it.found)continue;const dx=it.x-h.x,dz=it.z-h.z;
    if(dx*dx+dz*dz<(h.r*0.9)**2&&it.depth>h.d&&it.depth-h.d<HINT_AHEAD)hintFind(it,h);   // the shovel clinks on it a scoop or two early
    if(dx*dx+dz*dz<(h.r*0.9)**2&&it.depth<=h.d){
      if(!LOOT[it.type].key&&!LOOT[it.type].heavy&&S.sack.length>=sackMax()){if(now-lastWarn>2500){lastWarn=now;toast(`Your sack is full (${sackMax()} items). Sell to Mr. Sir, then come back for it.`,'bad')}continue}
      foundItem(it,h);
    }
  }
}
function foundItem(it,h){
  it.found=true;wsSend({t:'got',item:it.id,kb:it.type==='kb'});popItem(it,h.x,h.z);
  const L=LOOT[it.type];
  logEv('found',{item:it.id,type:it.type,value:L.val,x:+h.x.toFixed(1),z:+h.z.toFixed(1),heavy:!!L.heavy,kb:it.type==='kb'});
  if(it.type==='suitcase'){sfx.gold();triggerWin(S.name,true);return}
  if(it.type==='kb'){S.hasKB=true;sfx.gold();toast('A gold tube marked "KB"! The Warden will want this. Take it to her cabin.','gold',6000);shout(2);return}
  if(L.heavy){sfx.clank();sfx.gold();addXP(20);toast(`You hit something big: ${L.name} (${L.val} seeds). It won't fit in your sack. Grab it with F and haul it to Mr. Sir's pickup, just inside the main gate. Two campers carry it much faster.`,'gold',7000);
    if(online())wsSend({t:'prop',item:it.id,type:it.type,x:h.mx,z:h.mz});else addProp(it.id,it.type,h.mx,h.mz);return}
  S.sack.push(it.type);sfx.find();sfx.clank();addXP(4+L.val/4);toast(`Found: ${L.name} (worth ${L.val} seeds). Sell it to Mr. Sir.`+(L.val>=40?' A rare one!':''),L.val>=40?'gold':'',3200);
}

/* ---------- interactions ---------- */
function nearSpot(){
  const dn=remoteNear(R=>R.f&2,2.4);if(dn)return{id:'revive',...dn};
  const tr=remoteNear(R=>R.f&16,3);if(tr)return{id:'pull',...tr};
  const sk=remoteNear(R=>R.f&32,SINK_RESCUE_R);if(sk)return{id:'sinkRescue',...sk};   // link hands with a sinkhole-trapped friend (hold F: see 87-sinkhole.js)
  if(S.carry!=null&&PROPS.has(S.carry))return{id:'drop',pr:PROPS.get(S.carry)};
  if(!inTent()){
    const pr=propNear(2.4);if(pr)return{id:'prop',pr};
    const b=bagNear(2);if(b)return{id:'bag',b};
  }
  for(const s of SPOTS){
    const roomSpot=s.id==='exit'||s.id==='bunk'||s.id==='cards'||s.id==='office';
    if(roomSpot?S.tent==null||(s.ti!=null&&s.ti!==S.tent)||(s.id==='bunk'&&BUNKS[s.bi].tent!==S.tent)||(s.id==='cards'&&S.tent!==TENTS.indexOf(D_TENT)):S.tent!=null)continue;
    if((P.x-s.x)**2+(P.z-s.z)**2<s.r*s.r)return s;
  }
  let best=null,bd=2.8*2.8;
  for(const b of bots){if(!b.p.g.visible)continue;const dx=b.p.g.position.x-P.x,dz=b.p.g.position.z-P.z,d2=dx*dx+dz*dz;if(d2<bd){bd=d2;best=b}}
  return best?{id:'bot',bot:best}:null;
}
function use(){
  const s=nearSpot();if(!s||S.ko||uiOpen())return;
  if(s.id==='revive')return; // hold F: handled in updateCoop
  if(s.id==='pull'){wsSend({t:'pull',id:s.rid});addXP(15);toast(`You pulled ${s.R.name} out of the hole.`,'good',2000);sfx.thud();return}
  if(s.id==='sinkRescue')return; // hold F to link hands: handled every frame in updateSinkholes (87-sinkhole.js)
  if(s.id==='drop'){S.carry=null;toast('You let go.','',1200);return}
  if(s.id==='prop'){S.carry=s.pr.id;digHeld=false;logEv('propGrab',{item:s.pr.id,type:s.pr.type,x:+s.pr.x.toFixed(1),z:+s.pr.z.toFixed(1)});toast(`Hauling the ${LOOT[s.pr.type].name}. Get it to Mr. Sir's pickup by the main gate. A friend grabbing it too makes it way faster. F to let go.`,'',4000);sfx.thud();return}
  if(s.id==='bag'){if(online())wsSend({t:'grab',id:s.b.id});else{takeBag(s.b.items,s.b.n);removeBag(s.b.id)}return}
  if(s.id==='sir')openDialog('sir');
  else if(s.id==='warden')openDialog('warden');
  else if(s.id==='store')openShop();
  else if(s.id==='cards')openCards();
  else if(s.id==='office')toast('The Warden\'s ledgers cover every camper, every hole, and every found object.','',4000);
  else if(s.id==='bot')openDialog('bot',s.bot);
  else if(s.id==='tentdoor')enterTent(s.ti);
  else if(s.id==='exit')exitTent();
  else if(s.id==='bunk')toggleBunk(s.bi);
}
